import{_ as t,c as i,o as a,ag as r}from"./chunks/framework.CB_NIqHd.js";const g=JSON.parse('{"title":"Which metrics do you use to measure quality of your code?","description":"","frontmatter":{},"headers":[],"relativePath":"senior_growth/Clean_code_and_Code_Quality/Which_metrics_do_you_use_to_measure_quality_of_your_code.md","filePath":"senior_growth/Clean_code_and_Code_Quality/Which_metrics_do_you_use_to_measure_quality_of_your_code.md"}'),n={name:"senior_growth/Clean_code_and_Code_Quality/Which_metrics_do_you_use_to_measure_quality_of_your_code.md"};function o(s,e,l,d,c,u){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="which-metrics-do-you-use-to-measure-quality-of-your-code" tabindex="-1">Which metrics do you use to measure quality of your code? <a class="header-anchor" href="#which-metrics-do-you-use-to-measure-quality-of-your-code" aria-label="Permalink to “Which metrics do you use to measure quality of your code?”">​</a></h1><h1 id="📊-code-quality-metrics" tabindex="-1">📊 Code Quality Metrics <a class="header-anchor" href="#📊-code-quality-metrics" aria-label="Permalink to “📊 Code Quality Metrics”">​</a></h1><p>Measuring code quality is essential for <strong>maintainability, reliability, and scalability</strong>. These are candidate signals for a project; they are not a claim of personal project experience or universal thresholds:</p><hr><h2 id="_1️⃣-code-coverage" tabindex="-1">1️⃣ Code Coverage <a class="header-anchor" href="#_1️⃣-code-coverage" aria-label="Permalink to “1️⃣ Code Coverage”">​</a></h2><ul><li><strong>Definition:</strong> Percentage of code executed by automated tests.</li><li><strong>Tools:</strong> Jest, Vitest, Mocha + NYC/Istanbul, SonarQube</li><li><strong>Example starting point:</strong> 80% coverage may be a team gate, not a universal quality target. Select line/branch/function thresholds based on risk and exclusions.</li><li><strong>Why important:</strong> Shows which instrumented code executed; assertions and negative cases determine whether important behavior was checked.</li></ul><hr><h2 id="_2️⃣-cyclomatic-complexity" tabindex="-1">2️⃣ Cyclomatic Complexity <a class="header-anchor" href="#_2️⃣-cyclomatic-complexity" aria-label="Permalink to “2️⃣ Cyclomatic Complexity”">​</a></h2><ul><li><strong>Definition:</strong> Measures the number of <strong>independent paths</strong> through a function or method.</li><li><strong>Tools:</strong> SonarQube, ESLint plugins, Plato</li><li><strong>Example review trigger:</strong> complexity above 10 can prompt inspection; tool counting rules and domain complexity matter.</li><li><strong>Why important:</strong> High complexity increases <strong>risk of bugs and maintenance difficulty</strong>.</li></ul><hr><h2 id="_3️⃣-code-duplication" tabindex="-1">3️⃣ Code Duplication <a class="header-anchor" href="#_3️⃣-code-duplication" aria-label="Permalink to “3️⃣ Code Duplication”">​</a></h2><ul><li><strong>Definition:</strong> Percentage of repeated code across the codebase.</li><li><strong>Tools:</strong> SonarQube, PMD, ESLint plugins</li><li><strong>Example review trigger:</strong> 5% duplicated syntax is a diagnostic, not a universal failure threshold; duplicated domain knowledge matters more.</li><li><strong>Why important:</strong> Reduces maintenance overhead and ensures DRY principles.</li></ul><hr><h2 id="_4️⃣-linting-style-compliance" tabindex="-1">4️⃣ Linting / Style Compliance <a class="header-anchor" href="#_4️⃣-linting-style-compliance" aria-label="Permalink to “4️⃣ Linting / Style Compliance”">​</a></h2><ul><li><strong>Definition:</strong> Adherence to coding standards and style guides.</li><li><strong>Tools:</strong> ESLint, Prettier, Stylelint</li><li><strong>Goal:</strong> Zero linting errors</li><li><strong>Why important:</strong> Consistent code improves readability and reduces cognitive load.</li></ul><hr><h2 id="_5️⃣-test-pass-rate" tabindex="-1">5️⃣ Test Pass Rate <a class="header-anchor" href="#_5️⃣-test-pass-rate" aria-label="Permalink to “5️⃣ Test Pass Rate”">​</a></h2><ul><li><strong>Definition:</strong> Percentage of tests passing in the CI pipeline.</li><li><strong>Tools:</strong> Jest, Vitest, Cypress, Playwright</li><li><strong>Goal:</strong> 100% passing</li><li><strong>Why important:</strong> Failing tests indicate potential regressions or unstable code.</li></ul><hr><h2 id="_6️⃣-security-vulnerabilities" tabindex="-1">6️⃣ Security Vulnerabilities <a class="header-anchor" href="#_6️⃣-security-vulnerabilities" aria-label="Permalink to “6️⃣ Security Vulnerabilities”">​</a></h2><ul><li><strong>Definition:</strong> Detection of known vulnerabilities in code or dependencies.</li><li><strong>Tools:</strong> SonarQube, Snyk, npm audit, Dependabot</li><li><strong>Goal:</strong> Zero critical/high vulnerabilities</li><li><strong>Why important:</strong> Prevents security issues and production risks.</li></ul><hr><h2 id="_7️⃣-maintainability-technical-debt" tabindex="-1">7️⃣ Maintainability / Technical Debt <a class="header-anchor" href="#_7️⃣-maintainability-technical-debt" aria-label="Permalink to “7️⃣ Maintainability / Technical Debt”">​</a></h2><ul><li><strong>Definition:</strong> A composite metric often calculated by tools like SonarQube.</li><li><strong>Goal:</strong> High maintainability rating, low technical debt</li><li><strong>Why important:</strong> Highlights code worth inspecting. Tool-estimated debt is based on configured remediation estimates, not a forecast of actual team delivery time.</li></ul><hr><h2 id="_8️⃣-performance-bundle-metrics-optional-for-frontend" tabindex="-1">8️⃣ Performance / Bundle Metrics (Optional for Frontend) <a class="header-anchor" href="#_8️⃣-performance-bundle-metrics-optional-for-frontend" aria-label="Permalink to “8️⃣ Performance / Bundle Metrics (Optional for Frontend)”">​</a></h2><ul><li><strong>Definition:</strong> Measures load time, bundle size, and runtime performance.</li><li><strong>Tools:</strong> Webpack Bundle Analyzer, Lighthouse, Chrome DevTools</li><li><strong>Goal:</strong> Optimized bundles, fast first load</li><li><strong>Why important:</strong> Impacts user experience and scalability.</li></ul><hr><h3 id="✅-summary-table" tabindex="-1">✅ Summary Table <a class="header-anchor" href="#✅-summary-table" aria-label="Permalink to “✅ Summary Table”">​</a></h3><table tabindex="0"><thead><tr><th>Metric</th><th>Tool</th><th>Goal</th><th>Importance</th></tr></thead><tbody><tr><td>Code coverage</td><td>Jest, Vitest, SonarQube</td><td>Risk-based thresholds; 80% only an example</td><td>Executed code, not assertion quality</td></tr><tr><td>Cyclomatic complexity</td><td>SonarQube, ESLint</td><td>Contextual review trigger; 10 example</td><td>Inspect branching and change risk</td></tr><tr><td>Code duplication</td><td>SonarQube</td><td>Contextual review trigger; 5% example</td><td>Inspect shared domain knowledge</td></tr><tr><td>Linting</td><td>ESLint, Prettier</td><td>0 errors</td><td>Consistent style</td></tr><tr><td>Test pass rate</td><td>Jest, Cypress</td><td>100%</td><td>Prevent regressions</td></tr><tr><td>Security</td><td>Snyk, SonarQube</td><td>No critical issues</td><td>Secure code</td></tr><tr><td>Maintainability</td><td>SonarQube</td><td>High rating</td><td>Reduce technical debt</td></tr><tr><td>Performance</td><td>Lighthouse</td><td>Optimized</td><td>Better UX</td></tr></tbody></table><hr><h3 id="✅-key-takeaways" tabindex="-1">✅ Key Takeaways <a class="header-anchor" href="#✅-key-takeaways" aria-label="Permalink to “✅ Key Takeaways”">​</a></h3><ul><li><strong>Quality metrics</strong> provide signals that need behavioral evidence and context.</li><li>They help <strong>detect risks early</strong>, enforce standards, and improve maintainability.</li><li>Use <strong>CI/CD pipelines</strong> to enforce these metrics automatically for every merge.</li></ul><blockquote><p>💡 Senior Tip:<br> Focus on <strong>meaningful metrics</strong>—coverage alone isn’t enough; combine with complexity, duplication, and maintainability to get a full picture.</p></blockquote><h2 id="turn-a-signal-into-a-decision" tabindex="-1">Turn a signal into a decision <a class="header-anchor" href="#turn-a-signal-into-a-decision" aria-label="Permalink to “Turn a signal into a decision”">​</a></h2><p>For a critical authorization or payment invariant, require direct allowed/denied/boundary tests even if overall coverage exceeds a gate. For generated adapters, document exclusions instead of inflating the denominator invisibly. A high-complexity parser may need clearer state transitions and property tests; splitting it into many trivial functions just to lower a score can hide the same complexity. A shared tax rule deserves one authority, while repeated multiplication across unrelated concepts need not be unified.</p><p>The <a href="./../Testing/TDD_-_pros_and_cons(red,_green,_refactor).html#config-tdd">executed TDD feature</a> records 3 pass/5 fail for a bad stub and 8 pass after implementation/refactor. Those tests assert contract boundaries and failures; no coverage percentage was measured for that fixture. The passing suite initially needed an additional newline edge case, demonstrating why “all tests pass” cannot prove completeness. A retry that turns red into green without investigating can conceal a flaky test; retain first-run failures and report retries separately from the eligible first-run pass rate.</p><p>Security scanner results identify known signatures/advisories; zero reported vulnerabilities does not prove the absence of exploitable issues. Review reachability, authorization, data exposure, runtime configuration and remediation urgency. Performance needs explicit device/network/workload, percentiles and observation window, as in <a href="./../EngX_Quality/Could_please_the_differentiate_between_Functional_and_Non-functional_reqs(NFRs),_How_and_when_to_take_them_into_consideration.html#quality-scenarios-and-acceptance-evidence">the quality scenarios</a>.</p><p><strong>Exercise acceptance:</strong> choose one risk, record a baseline and a candidate threshold with denominator/exclusions, add a defect that a meaningful assertion catches, then show how the metric and actual behavior differ. Retain first-run failures, tool/version/config and a reasoned improvement decision. Do not report a tool&#39;s debt-hours as an engineering estimate; estimate the actual change with dependencies and uncertainty. Learner practice remains required. <a href="https://jestjs.io/docs/configuration#coveragethreshold-object" target="_blank" rel="noreferrer">Jest&#39;s official threshold configuration</a> explains enforceable gates; it does not choose an appropriate risk policy for the team.</p>',39)])])}const m=t(n,[["render",o]]);export{g as __pageData,m as default};
